import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define CT_TD 8
#define CT_TH 8
#define CT_TW 16
#define CT_CO 4
#define CT_THREADS 256
// ---------------------------------------------------------------------
// Fallback direct kernel: one thread per output voxel.
// Handles arbitrary stride / padding / output_padding / groups.
// ---------------------------------------------------------------------
__global__ void conv_transpose3d_direct_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int B, int Cin, int Cout,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int groups, bool has_bias)
{
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)B * Cout * Dout * Hout * Wout;
    if (idx >= total) return;
    int w_out = (int)(idx % Wout);
    long t = idx / Wout;
    int h_out = (int)(t % Hout);
    t /= Hout;
    int d_out = (int)(t % Dout);
    t /= Dout;
    int c_out = (int)(t % Cout);
    int b = (int)(t / Cout);
    int Cout_per_group = Cout / groups;
    int Cin_per_group = Cin / groups;
    int g = c_out / Cout_per_group;
    int c_out_local = c_out - g * Cout_per_group;
    int c_in_start = g * Cin_per_group;
    float acc = 0.0f;
    for (int c_in = c_in_start; c_in < c_in_start + Cin_per_group; ++c_in) {
        const float* w_ptr = weight + ((long)c_in * Cout_per_group + c_out_local) * (long)kD * kH * kW;
        const float* x_ptr = x + ((long)b * Cin + c_in) * (long)D * H * W;
        for (int kd = 0; kd < kD; ++kd) {
            int tmp_d = d_out + pad_d - kd;
            if (tmp_d < 0 || (tmp_d % stride_d) != 0) continue;
            int d_in = tmp_d / stride_d;
            if (d_in >= D) continue;
            for (int kh = 0; kh < kH; ++kh) {
                int tmp_h = h_out + pad_h - kh;
                if (tmp_h < 0 || (tmp_h % stride_h) != 0) continue;
                int h_in = tmp_h / stride_h;
                if (h_in >= H) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    int tmp_w = w_out + pad_w - kw;
                    if (tmp_w < 0 || (tmp_w % stride_w) != 0) continue;
                    int w_in = tmp_w / stride_w;
                    if (w_in >= W) continue;
                    acc += x_ptr[((long)d_in * H + h_in) * W + w_in] *
                           w_ptr[((long)kd * kH + kh) * kW + kw];
                }
            }
        }
    }
    if (has_bias) acc += bias[c_out];
    out[idx] = acc;
}
// ---------------------------------------------------------------------
// Cooperative tiled kernel (structural rewrite of the direct kernel):
//  * each CTA computes a CT_TD x CT_TH x CT_TW tile of the output for
//    CT_CO output channels of one batch element
//  * the required (CT_TD+K-1) x (CT_TH+K-1) x (CT_TW+K-1) input patch is
//    staged in shared memory once per input channel and reused by all
//    256 threads and all CT_CO output channels (strong cooperative reuse)
//  * each thread computes a 1x2x2 output sub-block for CT_CO channels
//    with register blocking (input rows cached in registers across kw)
// Requires: stride == 1, cubic kernel K, Cout_per_group % CT_CO == 0.
// ---------------------------------------------------------------------
template <int K>
__global__ void conv_transpose3d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int B, int Cin, int Cout,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int pad_d, int pad_h, int pad_w,
    int Cout_per_group, int Cin_per_group,
    int tiles_d, int tiles_h, int tiles_w,
    bool has_bias)
{
    constexpr int SD = CT_TD + K - 1;
    constexpr int SH = CT_TH + K - 1;
    constexpr int SW = CT_TW + K - 1;
    constexpr int KK = K * K * K;
    __shared__ float s_in[SD * SH * SW];
    __shared__ float s_w[CT_CO * KK];
    int tile_id = blockIdx.x;
    int tw = tile_id % tiles_w;
    int t = tile_id / tiles_w;
    int th = t % tiles_h;
    int td = t / tiles_h;
    int d0 = td * CT_TD;
    int h0 = th * CT_TH;
    int w0 = tw * CT_TW;
    int c_out0 = blockIdx.y * CT_CO;
    int b = blockIdx.z;
    int g = c_out0 / Cout_per_group;
    int c_out_local0 = c_out0 - g * Cout_per_group;
    int c_in_start = g * Cin_per_group;
    int tid = threadIdx.x;
    int dd = tid % CT_TD;
    int hh = (tid / CT_TD) % (CT_TH / 2);
    int ww = tid / (CT_TD * (CT_TH / 2));
    int d_out = d0 + dd;
    int h_out = h0 + hh * 2;
    int w_out = w0 + ww * 2;
    bool d_ok = d_out < Dout;
    bool h_ok0 = h_out < Hout;
    bool h_ok1 = (h_out + 1) < Hout;
    bool w_ok0 = w_out < Wout;
    bool w_ok1 = (w_out + 1) < Wout;
    float acc[CT_CO][2][2];
    #pragma unroll
    for (int co = 0; co < CT_CO; ++co)
        #pragma unroll
        for (int i = 0; i < 2; ++i)
            #pragma unroll
            for (int j = 0; j < 2; ++j)
                acc[co][i][j] = 0.0f;
    const int id0 = d0 + pad_d - (K - 1);
    const int ih0 = h0 + pad_h - (K - 1);
    const int iw0 = w0 + pad_w - (K - 1);
    for (int c_in = c_in_start; c_in < c_in_start + Cin_per_group; ++c_in) {
        const float* x_ptr = x + ((long)b * Cin + c_in) * (long)D * H * W;
        #pragma unroll 4
        for (int i = tid; i < SD * SH * SW; i += CT_THREADS) {
            int sd = i / (SH * SW);
            int r = i - sd * (SH * SW);
            int sh = r / SW;
            int sw = r - sh * SW;
            int di = id0 + sd;
            int hi = ih0 + sh;
            int wi = iw0 + sw;
            float v = 0.0f;
            if (di >= 0 && di < D && hi >= 0 && hi < H && wi >= 0 && wi < W)
                v = x_ptr[((long)di * H + hi) * W + wi];
            s_in[i] = v;
        }
        const float* w_base = weight + ((long)c_in * Cout_per_group + c_out_local0) * (long)KK;
        if (tid < CT_CO * KK) s_w[tid] = w_base[tid];
        __syncthreads();
        const int sd_base = dd + (K - 1);
        const int sh_base = hh * 2 + (K - 1);
        const int sw_base = ww * 2;
        #pragma unroll
        for (int kd = 0; kd < K; ++kd) {
            int sd = sd_base - kd;
            #pragma unroll
            for (int kh = 0; kh < K; ++kh) {
                int sh = sh_base - kh;
                const float* row0 = s_in + (sd * SH + sh) * SW + sw_base;
                const float* row1 = row0 + SW;
                float r0[K + 1];
                float r1[K + 1];
                #pragma unroll
                for (int i = 0; i <= K; ++i) {
                    r0[i] = row0[i];
                    r1[i] = row1[i];
                }
                #pragma unroll
                for (int kw = 0; kw < K; ++kw) {
                    float v00 = r0[K - 1 - kw];
                    float v01 = r0[K - kw];
                    float v10 = r1[K - 1 - kw];
                    float v11 = r1[K - kw];
                    int tap = (kd * K + kh) * K + kw;
                    #pragma unroll
                    for (int co = 0; co < CT_CO; ++co) {
                        float wv = s_w[co * KK + tap];
                        acc[co][0][0] = fmaf(v00, wv, acc[co][0][0]);
                        acc[co][0][1] = fmaf(v01, wv, acc[co][0][1]);
                        acc[co][1][0] = fmaf(v10, wv, acc[co][1][0]);
                        acc[co][1][1] = fmaf(v11, wv, acc[co][1][1]);
                    }
                }
            }
        }
        __syncthreads();
    }
    if (!d_ok) return;
    #pragma unroll
    for (int co = 0; co < CT_CO; ++co) {
        int c_out = c_out0 + co;
        float bv = has_bias ? bias[c_out] : 0.0f;
        long base = (((long)b * Cout + c_out) * Dout + d_out) * (long)Hout;
        if (h_ok0) {
            if (w_ok0) out[(base + h_out) * Wout + w_out] = acc[co][0][0] + bv;
            if (w_ok1) out[(base + h_out) * Wout + w_out + 1] = acc[co][0][1] + bv;
        }
        if (h_ok1) {
            if (w_ok0) out[(base + h_out + 1) * Wout + w_out] = acc[co][1][0] + bv;
            if (w_ok1) out[(base + h_out + 1) * Wout + w_out + 1] = acc[co][1][1] + bv;
        }
    }
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.is_cuda() && weight.scalar_type() == at::kFloat, "weight must be CUDA float32");
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    int B = xc.size(0);
    int Cin = xc.size(1);
    int D = xc.size(2);
    int H = xc.size(3);
    int W = xc.size(4);
    int kD = wc.size(2);
    int kH = wc.size(3);
    int kW = wc.size(4);
    int Cout = (int)(wc.size(1) * groups);
    int Dout = (int)((D - 1) * stride_d - 2 * pad_d + kD + out_pad_d);
    int Hout = (int)((H - 1) * stride_h - 2 * pad_h + kH + out_pad_h);
    int Wout = (int)((W - 1) * stride_w - 2 * pad_w + kW + out_pad_w);
    auto out = torch::empty({B, Cout, Dout, Hout, Wout}, xc.options());
    long total = (long)B * Cout * Dout * Hout * Wout;
    if (total == 0) return out;
    const float* bias_ptr = nullptr;
    bool has_bias = bias.defined() && bias.numel() > 0;
    torch::Tensor bc;
    if (has_bias) {
        bc = bias.contiguous();
        bias_ptr = bc.data_ptr<float>();
    }
    int Cout_per_group = Cout / (int)groups;
    int Cin_per_group = Cin / (int)groups;
    bool stride_one = (stride_d == 1 && stride_h == 1 && stride_w == 1);
    bool cubic = (kD == kH) && (kH == kW);
    bool co_ok = (Cout_per_group % CT_CO) == 0;
    if (stride_one && cubic && co_ok && kD >= 1 && kD <= 7) {
        int tiles_d = (Dout + CT_TD - 1) / CT_TD;
        int tiles_h = (Hout + CT_TH - 1) / CT_TH;
        int tiles_w = (Wout + CT_TW - 1) / CT_TW;
        dim3 grid((unsigned int)(tiles_d * tiles_h * tiles_w),
                  (unsigned int)(Cout / CT_CO),
                  (unsigned int)B);
#define LAUNCH_TILED(KVAL) \
        conv_transpose3d_tiled_kernel<KVAL><<<grid, CT_THREADS>>>( \
            xc.data_ptr<float>(), wc.data_ptr<float>(), bias_ptr, out.data_ptr<float>(), \
            B, Cin, Cout, D, H, W, Dout, Hout, Wout, \
            (int)pad_d, (int)pad_h, (int)pad_w, \
            Cout_per_group, Cin_per_group, tiles_d, tiles_h, tiles_w, has_bias)
        switch (kD) {
            case 1: LAUNCH_TILED(1); break;
            case 2: LAUNCH_TILED(2); break;
            case 3: LAUNCH_TILED(3); break;
            case 4: LAUNCH_TILED(4); break;
            case 5: LAUNCH_TILED(5); break;
            case 6: LAUNCH_TILED(6); break;
            case 7: LAUNCH_TILED(7); break;
        }
#undef LAUNCH_TILED
    } else {
        int threads = 256;
        long blocks = (total + threads - 1) / threads;
        conv_transpose3d_direct_kernel<<<(unsigned int)blocks, threads>>>(
            xc.data_ptr<float>(),
            wc.data_ptr<float>(),
            bias_ptr,
            out.data_ptr<float>(),
            B, Cin, Cout, D, H, W,
            Dout, Hout, Wout,
            kD, kH, kW,
            (int)stride_d, (int)stride_h, (int)stride_w,
            (int)pad_d, (int)pad_h, (int)pad_w,
            (int)groups, has_bias);
    }
    return out;
}
'''

_cpp_src = r'''
torch::Tensor conv_transpose3d_forward(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t groups);
'''

_ext = load_inline(
    name="conv_transpose3d_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose3d_forward"],
    verbose=False,
)


def _to_triple(v):
    if isinstance(v, (tuple, list)):
        return int(v[0]), int(v[1]), int(v[2])
    return int(v), int(v), int(v)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias)
        self._stride = _to_triple(stride)
        self._padding = _to_triple(padding)
        self._output_padding = _to_triple(output_padding)
        self._groups = int(groups)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv_transpose3d.weight
        b = self.conv_transpose3d.bias
        if b is None:
            b = torch.empty(0, device=x.device, dtype=x.dtype)
        return _ext.conv_transpose3d_forward(
            x, w, b,
            self._stride[0], self._stride[1], self._stride[2],
            self._padding[0], self._padding[1], self._padding[2],
            self._output_padding[0], self._output_padding[1], self._output_padding[2],
            self._groups)

